CREATE TABLE public.waitlist (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT NOT NULL UNIQUE, use_case TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); ALTER TABLE public.waitlist ENABLE ROW LEVEL SECURITY; CREATE POLICY "join_waitlist" ON public.waitlist FOR INSERT TO anon, authenticated WITH CHECK (true); CREATE TABLE public.demo_memories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), namespace TEXT NOT NULL DEFAULT 'public', content TEXT NOT NULL, tags TEXT[] DEFAULT ARRAY[]::TEXT[], metadata JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); ALTER TABLE public.demo_memories ENABLE ROW LEVEL SECURITY; CREATE POLICY "demo_read" ON public.demo_memories FOR SELECT TO anon, authenticated USING (true); CREATE POLICY "demo_write" ON public.demo_memories FOR INSERT TO anon, authenticated WITH CHECK (true); CREATE INDEX demo_memories_ns_idx ON public.demo_memories (namespace, created_at DESC);